from pathlib import Path
import json,copy,hashlib
W=Path(__file__).resolve().parent;ROOT=W.parents[1]
# id, suggested duration, title, concept, function, reason, measured implementation, speech, transition
rows=[
('ifsc26_s01',20,'Mosquitos pelo som','Classificação acústica supervisionada.','Distinguir Aedes aegypti, outro mosquito e ausência de mosquito.','O voo contém estrutura temporal e espectral explorável por algoritmos.','Programa implementado com cascata clássica, LSTM e Bi-LSTM; os resultados são separados por modelo.','Este trabalho investiga a identificação de Aedes aegypti pelo som do voo. Vou mostrar como representamos o áudio, como treinamos os modelos e o que os resultados permitem concluir.','Primeiro, onde essa identificação pode ajudar?'),
('ifsc26_introducao_problema',50,'O áudio pode apoiar a vigilância do Aedes','Vigilância entomológica acompanha a presença dos vetores.','Vistorias, coleta e identificação morfológica orientam o controle.','A análise automática do voo pode acrescentar registros ao monitoramento.','Fotos de criadouros são exemplos de contexto; o algoritmo recebe áudio de adultos, não detecta larvas na água.','Hoje há vistorias e coleta de material, com identificação por características do mosquito usando lupa ou microscópio. A proposta é acrescentar uma forma de triagem pelo som do voo. Isso pode ajudar a registrar a presença de Aedes e apoiar o monitoramento. As fotos mostram locais com água acumulada para contextualizar o problema; não são focos localizados automaticamente pelo sistema.','Para isso, precisamos definir exatamente quais respostas o sistema deve dar.'),
('ifsc26_s02',40,'Um áudio deve levar a uma de três classes','Aprendizado supervisionado usa exemplos com rótulos conhecidos.','Ensinar a distinção entre Aedes aegypti, outros mosquitos e ruído.','Separar ruído evita forçar toda gravação a ser uma espécie de mosquito.','As saídas são 0=no_mosquito, 1=other_mosquito, 2=aedes_aegypti; a decisão reportada agrega janelas por grupo.','A tarefa tem três respostas: Aedes aegypti, outro mosquito ou ruído sem mosquito. Não queremos identificar cada uma das outras espécies. Durante o treinamento, exemplos rotulados mostram ao modelo qual é a resposta correta. Durante o teste, ele recebe novos grupos de gravação sem acesso ao rótulo. Também não estamos inferindo se o mosquito está infectado por dengue.','A escolha do áudio e das redes se apoia em trabalhos anteriores.'),
('ifsc26_s03',50,'A literatura orienta captura, memória e robustez','Trabalhos relacionados fornecem técnicas e protocolos de comparação.','Fundamentar aquisição acústica, modelagem temporal e tratamento de ruído.','Não é preciso reinventar cada etapa; técnicas são adaptadas à tarefa ternária.','Mukundarajan 2017: celulares; Torres 2025: LSTM/Bi-LSTM e MC dropout para infectado/saudável; Supratak 2024: MosquitoSong+ e robustez.','O primeiro estudo demonstra a aquisição acústica com celulares. O segundo usa LSTM e avaliação de incerteza em outra tarefa: distinguir fêmeas Aedes infectadas de saudáveis. Adaptamos as técnicas para nossas três classes. MosquitoSong+ usa redes convolucionais e ajuda a discutir robustez ao ruído. Uma CNN aprende padrões locais do sinal; a LSTM, que testamos aqui, aprende relações ao longo do tempo. Os números dos artigos não são resultados do nosso detector.','Antes de discutir a rede, precisamos conhecer os dados que ela recebeu.'),
('ifsc26_s08',85,'Separar grupos permite avaliar o aprendizado','Uma janela é um trecho de áudio; um grupo reúne janelas da mesma unidade de gravação.','Evitar que trechos de uma mesma gravação apareçam simultaneamente no ajuste e no teste.','Cortes próximos compartilham som e condições de aquisição; tratá-los como testes independentes favorece estimativas otimistas.','Dryad 613 grupos; HumBug 592; ESC-50 289. Total 42.029 janelas, 1.494 grupos, 1.441 blocos PCM. Classes: 426 ruído, 1.008 outros, 60 Aedes. Cinco dobras externas por grupo; LSTM: holdout interno agrupado escolhe época e limiares.','Dryad e HumBug fornecem mosquitos e sons de fundo; ESC-50 acrescenta sons ambientais. São 1.494 grupos, com apenas sessenta da classe-alvo. Cada grupo é testado uma vez no rodízio de cinco dobras: quatro ficam para o desenvolvimento e uma para o teste. Dentro do desenvolvimento, separamos validação para escolher época e limiares. A normalização é ajustada só no treino. Janelas, grupos e indivíduos não são a mesma coisa. A cascata e as redes usam a mesma população e as mesmas dobras de teste.','Agora podemos acompanhar a transformação de uma janela real de áudio.'),
('ifsc26_s04',45,'A FFT revela as frequências presentes no trecho','FFT é um algoritmo para calcular a transformada discreta de Fourier.','Decompor o sinal temporal em componentes de frequência.','O padrão de vários componentes ajuda a caracterizar o som do voo.','Mesmo trecho real de 0,992 s a 8 kHz: forma de onda e módulo da FFT com Hann, nível relativo ao pico.','À esquerda vemos como a amplitude muda no tempo. À direita, a FFT mostra quais frequências estão presentes no mesmo trecho. Picos podem representar periodicidade e harmônicos. A amostragem de oito quilohertz é a taxa de leitura do áudio, não a frequência do batimento das asas. Essa vista resume o trecho inteiro; ainda não mostra em que momento cada componente aparece.','Também precisamos entender por que uma única frequência não resume o voo.'),
('ifsc26_s05',40,'Frequência fundamental e harmônicos','Fundamental é o ritmo periódico básico; harmônicos são componentes em seus múltiplos.','Relacionar o espectro à vibração periódica das asas.','Frequência, harmônicos e variação temporal oferecem pistas complementares.','Médias publicadas por Sinka et al. a 25 °C: Aedes aegypti fêmeas 458 Hz e machos 715 Hz; demais valores são referências da literatura, não limites do detector.','A frequência do voo varia entre condições e grupos biológicos. Neste exemplo da literatura, fêmeas e machos têm médias diferentes. Harmônicos aparecem em múltiplos da frequência básica. Por isso a rede recebe um padrão de frequências e sua evolução, em vez de apenas uma regra como procurar quinhentos hertz. Os valores mostrados aqui são publicados e não uma medição de todas as nossas gravações.','Para preservar a evolução dessas frequências, usamos a STFT.'),
('ifsc26_s06',45,'A STFT localiza as frequências ao longo do voo','STFT é a transformada de Fourier de curta duração, calculada em janelas sucessivas.','Construir o espectrograma: tempo no eixo horizontal, frequência no vertical e energia na cor.','Uma passagem de voo muda dentro do trecho; a FFT global perde essa localização temporal.','Hann de 1.024 amostras a 8 kHz =128 ms; avanço de128 amostras =16 ms; espaçamento dos bins 7,8125 Hz. A janela de classificação tem0,992 s, diferente da janela interna da STFT.','A STFT repete a análise de Fourier em pequenos intervalos. Assim, conseguimos enxergar a evolução do espectro. Aqui, cores mais claras indicam maior energia relativa, e as faixas horizontais mostram componentes persistentes. Usamos uma janela de cento e vinte e oito milissegundos, avançando dezesseis milissegundos por vez. Esses intervalos pertencem ao processamento dentro de cada trecho de quase um segundo.','O espectrograma ainda pode ser resumido em uma representação mais compacta.'),
('ifsc26_s07',55,'As bandas mel formam a sequência de entrada','Filtros mel agregam a potência espectral em bandas com espaçamento não uniforme.','Produzir vetores compactos de energia para alimentar a rede temporal.','Preserva a organização temporal e reduz a dimensionalidade do espectro completo.','64 bandas HTK entre80–4.000 Hz,55 passos. DC/RMS por janela; log-potência relativa limitada a[-80,0] dB; média/desvio por banda ajustados apenas no fit.','Cada coluna desta matriz representa um instante e cada linha uma banda mel. Portanto, uma entrada tem cinquenta e cinco vetores de sessenta e quatro valores. As cores mostram energia em decibéis. A escala mel concentra mais detalhe nas frequências baixas e resume as altas. A normalização torna as escalas mais comparáveis, mas seus parâmetros são calculados só nos dados de ajuste. Essa matriz é a sequência que a LSTM acompanha.','Com a entrada definida, vamos comparar dois modos de tomar a decisão.'),
('ifsc26_s11',60,'A cascata organiza a decisão em duas etapas','Cascata é uma organização da decisão; ensemble combina mais de um modelo.','Separar presença de mosquito e depois a identificação de Aedes.','Uma referência clássica permite avaliar o que a rede profunda acrescenta.','Regressão logística: separação linear nos atributos; HistGradientBoosting: conjunto de árvores ajustadas por boosting. Escores por janela são combinados; agregação com peso(1-p_ruído)^1,5; dois limiares definidos internamente.','A regressão logística aprende separações lineares entre os atributos acústicos. O HistGB usa árvores e pode representar relações não lineares. Combinamos os escores e damos mais peso às janelas consideradas ativas. A regra então passa por dois limiares: primeiro decide ruído ou mosquito; depois decide Aedes ou outro mosquito. Cascata descreve essas etapas de decisão, não é o nome de uma rede neural. Ela é nossa referência de comparação.','A alternativa profunda tenta aprender a evolução temporal a partir da sequência mel.'),
('ifsc26_s09',90,'LSTM e Bi-LSTM aprendem relações no tempo','LSTM é uma rede recorrente com memória controlada por portas; Bi-LSTM processa a sequência em dois sentidos.','Relacionar quadros mel consecutivos para classificar o trecho.','O padrão do voo evolui no tempo; memória pode reunir informação de vários instantes.','Duas camadas,128 unidades por direção,dropout0,20; projeção linear da última saída para3 escores e softmax. LSTM231.811 parâmetros; Bi-LSTM594.691.','A LSTM recebe a sequência quadro a quadro. Suas portas controlam o que entra, permanece ou sai da memória. Na versão bidirecional, uma recorrência percorre a sequência do início ao fim e outra do fim ao início. Cada bloco no desenho é uma camada, não um instante. No final, uma camada linear produz três escores e o softmax os transforma em probabilidades que somam um. As duas arquiteturas foram treinadas de fato para a tarefa ternária. A hipótese é que o contexto temporal ajude a reconhecer o voo.','Para aprender essas relações, precisamos transformar o erro em atualizações dos pesos.'),
('ifsc26_s12',55,'Adam transforma o erro em ajustes nos pesos','Entropia cruzada mede o erro; gradientes indicam como alterá-lo; Adam é um otimizador adaptativo.','Atualizar os parâmetros das redes a partir dos lotes rotulados.','Adam combina estimativas de direção e escala dos gradientes; clipping limita a norma para estabilizar o ajuste.','Adam,lr0,0006,lote256,clipping global3,máximo30 épocas. Hiperparâmetros fixados antes das métricas de teste; não há demonstração de ótimo global.','A entropia cruzada aumenta quando a rede dá pouca probabilidade à classe correta. A retropropagação calcula os gradientes desse erro. O Adam usa médias dos gradientes e de seus quadrados para adaptar a atualização dos pesos. A taxa de aprendizado controla o tamanho básico do passo. Também limitamos a norma dos gradientes em três, para evitar atualizações muito grandes. Esses são os parâmetros executados, não uma afirmação de que encontramos a configuração ótima.','Aprender o conjunto de treino é necessário, mas precisamos controlar a memorização.'),
('ifsc26_regularizacao',60,'Regularização e validação controlam o ajuste','Regularização reduz dependências excessivas do treino; validação orienta escolhas sem usar o teste.','Reduzir memorização e o domínio das classes ou gravações maiores.','Há desequilíbrio entre classes e quantidades diferentes de janelas por gravação.','Dropout0,20 entre camadas; amostragem ponderada por classe/gravação,gamma0,50 com contagem limitada a60; escolha pela menor perda por grupo,paciência5. MC dropout100 apenas na inferência adicional de WAV.','Dropout zera aleatoriamente vinte por cento das ativações entre as camadas durante o treino. A amostragem mantém a mesma massa total nas três classes e reduz o domínio das gravações com muitas janelas. A validação escolhe o checkpoint de menor perda; a paciência de cinco épocas permite tentar mais ajustes antes de parar. Na inferência adicional, cem passagens com dropout medem a discordância das decisões. As métricas de teste mostradas aqui usam inferência determinística.','As curvas registradas mostram como essa seleção ocorreu.'),
('ifsc26_s14',45,'A validação seleciona o checkpoint de cada rede','Época é um ciclo de amostragem e atualização; checkpoint é um estado salvo dos pesos.','Escolher o estado com menor erro de validação em vez de usar automaticamente a última época.','Mais treino não garante melhor desempenho em grupos que ficaram de fora.','Ajuste interno final: LSTM melhorépoca4, observadas9; Bi-LSTM melhorépoca2, observadas7; depois refit reiniciado por4/2 épocas no desenvolvimento completo. Curvas não representam a média das5 dobras.','A curva de treino continua caindo, mas a validação deixa de melhorar. A LSTM foi observada por nove épocas e o melhor ponto foi a quarta; a bidirecional, por sete, com melhor ponto na segunda. Depois, o ajuste é reiniciado no desenvolvimento completo pela quantidade selecionada. Os dois gráficos são do contexto final e não uma média das cinco dobras. Treino é medido por janela e validação por grupo, então não devemos comparar suas alturas como populações idênticas.','Com as escolhas encerradas, aplicamos os modelos aos grupos de teste.'),
('ifsc26_s15',55,'A cascata teve o maior acerto geral','Acurácia é a fração de classificações corretas entre todos os grupos avaliados.','Comparar o desempenho global nas mesmas três classes.','É uma visão inicial do resultado; deve ser acompanhada das métricas da classe-alvo.','Cascata1.345/1.494=90,03%;LSTM direta85,74%,calibrada86,55%;Bi direta82,33%,calibrada85,27%. Cada grupo contribui com uma decisão OOF.','A cascata acertou mil trezentos e quarenta e cinco dos mil quatrocentos e noventa e quatro grupos, chegando a noventa vírgula zero três por cento. As duas redes ficaram abaixo em acurácia geral. A decisão direta escolhe a classe com maior probabilidade agregada. A calibrada aplica dois limiares escolhidos na validação interna. Como a maioria dos grupos é de outros mosquitos, a acurácia sozinha não informa quantos Aedes conseguimos detectar.','Por isso precisamos observar sensibilidade e falsos positivos em conjunto.'),
('ifsc26_s10',85,'Detectar mais Aedes muda o número de alarmes','Sensibilidade mede alvos detectados; FPR mede negativos chamados de alvo.','Avaliar o compromisso entre perder Aedes e gerar alertas indevidos.','Acurácia global pode esconder comportamentos distintos na classe mais importante.','Cascata47/60=78,33%;LSTM direta52/60=86,67%;Bi direta53/60=88,33%. FPRs dividem os erros por426ruídos ou1.008outros. Calibração reduz alarmes e reduz recall das redes para20/60 e17/60.','A LSTM direta detectou cinquenta e dois Aedes, cinco a mais que a cascata. A bidirecional detectou cinquenta e três. Em troca, as duas chamaram mais ruídos e outros mosquitos de Aedes. Ao aplicar os limiares calibrados, os alarmes caíram, mas a sensibilidade também caiu bastante. Portanto, aumentar a acurácia ou reduzir o falso positivo isoladamente não basta. A escolha operacional depende do custo de perder um alvo e do custo de um alarme. Aqui mostramos todas as regras, sem escolher apenas a que ficou melhor no teste.','A matriz de confusão permite enxergar esses erros como contagens concretas.'),
('ifsc26_s17',55,'A matriz mostra quais classes foram confundidas','Matriz de confusão cruza classes reais nas linhas e previsões nas colunas.','Localizar os erros em cada par de classes e conferir os denominadores.','Contagens mostram a diferença entre detectar mosquito e identificar Aedes.','Diagonal324+974+47=1.345;13Aedes viraram outros;102ruídos viraram outros;23outros viraramAedes. PrecisãoAedes47/(47+23)=67,14%.','Na diagonal estão os acertos. Dos sessenta grupos Aedes, quarenta e sete foram reconhecidos e treze viraram outros mosquitos. Nenhum virou ruído. No outro sentido, vinte e três outros mosquitos foram chamados de Aedes. Assim, entre setenta alertas de Aedes, quarenta e sete estavam corretos: essa é a precisão de sessenta e sete vírgula quatorze por cento. Já a sensibilidade pergunta quantos dos Aedes existentes foram encontrados. São perguntas diferentes.','O próximo passo é coletar novos dados com condições e rótulos controlados.'),
('ifsc26_arduino_dataset',60,'O protótipo prepara a coleta de uma base própria','Dataset é um conjunto de exemplos com dados, rótulos e metadados.','Criar gravações compatíveis com o dispositivo e condições de uso propostas.','Uma base própria permite testar novas sessões com origem e protocolo conhecidos.','Fotos reais da montagem fornecidas pelo autor; protocolo futuro de microfone→USB→WAV,16kHz/16bitmono,checagem de integridade;trêsclasses,indivíduo,sessão,distância,temperatura,umidade.','As fotos mostram a montagem física e a placa conectada por USB. A próxima etapa é verificar a captura pelo microfone e salvar os arquivos WAV. Vamos incluir Aedes, outros mosquitos e controles sem mosquito, com identificação confirmada e registro de sessão e indivíduo. Parte da nova coleta será reservada antes de qualquer ajuste para avaliar o detector congelado. Somente a parcela de treino poderá ser usada depois para adaptação. Esses dados futuros não estão nos noventa por cento apresentados.','As fontes e os arquivos de apoio permitem rastrear cada etapa do trabalho.'),
('ifsc26_s19',20,'Referências e material de apoio','Referências e proveniência permitem rastrear afirmações e resultados.','Separar literatura, código, dados, imagens e medições locais.','A apresentação deve poder ser conferida e explicada além da exposição oral.','Artigos, documentação técnica, código e métricas estão nas notas; marca oficial IFSC; fotografias públicas creditadas e montagem fornecida pelo autor.','As referências fundamentam as escolhas, e os links completos estão nas notas. Os gráficos de resultados vêm dos experimentos do projeto. O material de apoio contém os conceitos, as contas e as transições para revisar a apresentação.','Para concluir, o que foi demonstrado e o que vem depois?'),
('ifsc26_s20',65,'Resultados, limites e próxima coleta','Generalização é manter desempenho em dados diferentes dos usados no ajuste.','Delimitar a conclusão científica e orientar a próxima avaliação.','Bom resultado no corpus não substitui avaliar novas sessões e dispositivos.','Avaliação retrospectiva por gravação/conteúdo; sessões e dispositivos podem repetir. MosquitoSong excluído do ajuste:0/4grupos Aedes; não é confirmação cega nova. Modelos têm seleção interna diferente e não houve ablação causal. Drive é enxame e está fora do escopo.','O programa profundo foi implementado e comparado como pede a disciplina. No corpus avaliado, a cascata teve maior acurácia geral, enquanto as redes diretas detectaram mais Aedes com mais alarmes. A conclusão é restrita a essa avaliação retrospectiva: separar gravações não prova independência de indivíduos, sessões ou microfones. MosquitoSong ficou fora do ajuste e seus quatro grupos Aedes não foram detectados. A próxima etapa é a coleta própria com teste reservado e detector congelado. Não demonstramos diagnóstico de infecção nem execução dessas redes na placa.','Encerrar e abrir a discussão.')]
assert sum(x[1] for x in rows)==1080 and len(rows)==20
prior=json.loads((ROOT/'output/ifsc_prototipo_fotos_2026_10_15/plan.json').read_text());oldnotes={x['slideId']:x['notes_full'] for x in prior}
plans=[]
for i,row in enumerate(rows,1):
 sid,sec,title,concept,fun,why,how,speech,transition=row
 source=oldnotes[sid].split('[Sources]',1)[1].split('[/Sources]',1)[0].strip()
 if sid=='ifsc26_s01':source=source.replace('https://www.ifsc.edu.br/campus-florianopolis','https://ifsc.edu.br/web/campus-florianopolis/identidade-visual\nhttps://ifsc.edu.br/documents/d/comunicacao/florianopolis')
 technical={'ifsc26_s09':'https://docs.pytorch.org/docs/2.14/generated/torch.nn.LSTM.html','ifsc26_s12':'https://docs.pytorch.org/docs/2.14/generated/torch.optim.Adam.html','ifsc26_s07':'Arquivo local: torres_lstm.py (MelSequence)'}
 if sid in technical:source+='\n'+technical[sid]
 source+='\nArquivo local: output/ifsc_didatica_2026_10_15/analise-lacunas.txt'
 notes=f'Tempo sugerido: {sec} segundos.\n\nConceito: {concept}\n\nPara que serve: {fun}\n\nPor que foi usado: {why}\n\nComo foi feito ou medido: {how}\n\nFala sugerida: {speech}\n\nTransição: {transition}\n\n[Sources]\n{source}\n[/Sources]'
 plans.append(dict(number=i,slideId=sid,seconds=sec,title=title,concept=concept,function=fun,why=why,how=how,speech=speech,transition=transition,notes_full=notes))
(W/'plan.json').write_text(json.dumps(plans,ensure_ascii=False,indent=2))
guide='GUIA DE ESTUDO E FALA — Luiz Eduardo do Nascimento Ciarallo\n\nRoteiro sugerido: 18 minutos; ensaiar com margem até 20. As explicações abaixo são apoio de estudo, não texto para ler integralmente.\n\n'+'\n\n'.join(f"{r['number']:02d}. {r['title']} — {r['seconds']} s\nO que é: {r['concept']}\nPara que serve: {r['function']}\nPor que foi usado: {r['why']}\nComo foi feito/medido: {r['how']}\nFala: {r['speech']}\nTransição: {r['transition']}" for r in plans)
guide+='''\n\nPERGUNTAS QUE PODEM APARECER\n\nOs 90,03% são da LSTM? Não. São da cascata LR + HistGB; LSTM direta tem 85,74% de acurácia geral.\n\nPor que usar rede profunda se a cascata teve mais acertos? A disciplina pede sua implementação; comparar arquiteturas testa uma hipótese e revela compromissos, mesmo quando a referência permanece melhor.\n\nO dataset Torres melhorou os 90,03%? Não foi integrado ao treino ternário. Os 300 tensores são de infectado/saudável e pertencem a outro estudo. Aqui adaptamos técnicas, não herdamos esse resultado como detector Aedes.\n\nÉpoca e janela são a mesma coisa? Não. Trecho de classificação: 0,992 s. Janela interna da STFT: 128 ms, avanço 16 ms. Época: ciclo de atualizações do treinamento com amostragem.\n\nComo surgem 55 passos? (7.936−1.024)/128+1 =55, sem preenchimento central.\n\nO que significa softmax? Transforma escores em valores positivos que somam um. Isso não garante probabilidades perfeitamente calibradas nem confiabilidade fora da distribuição.\n\nAcurácia e sensibilidade são iguais? Acurácia=(324+974+47)/1.494=90,03%. Sensibilidade Aedes=47/60=78,33%. Precisão Aedes=47/(47+23)=67,14%. FPR outros=23/1.008=2,28%. FPR ruído para Aedes=0/426=0%; ruído para qualquer mosquito=102/426=23,94%.\n\nO que significa calibrada aqui? Escolha de dois limiares pela validação interna; não significa prova de calibração probabilística ou garantia populacional de FPR.\n\nTreino/teste estão separados? Não há grupo de gravação nem bloco PCM atravessando as cinco dobras. Sessões/dispositivos podem se repetir; identidade biológica não foi demonstrada. A cascata usa calibração interna OOF; as redes usam um holdout interno agrupado. As dobras externas são iguais, os processos internos não.\n\nO modelo está rodando nessas fotos? As fotos documentam a montagem. Captura estruturada, novo dataset e porte das redes são etapas futuras; não apresentar como experimento embarcado já concluído.\n\nPor que o Drive saiu? É um enxame, fora do alvo de aquisição escolhido pelo autor. Não entrou nos resultados ternários. Originais históricos permanecem para auditoria.\n\nA intensidade mais variável faz o detector acertar? A análise descritiva mostrou diferenças entre fontes, mas não comprovou causalidade; dentro de Dryad/HumBug os erros não tinham menor variação. Não usar essa hipótese como explicação definitiva.\n\nO envio ao professor foi feito? Não. O material foi preparado e entregue ao autor no Drive; envio ao professor não foi solicitado.\n'''
(W/'Guia_de_estudo_e_fala.txt').write_text(guide)
(W/'Roteiro_apresentacao_IFSC.txt').write_text('\n\n'.join(f"{r['number']:02d}. {r['title']} ({r['seconds']} s)\n{r['speech']}\nTransição: {r['transition']}" for r in plans)+'\n\nTotal sugerido: 18min00s.\n')
print('20 slides; 18min00s; detailed concept/function/reason/method notes plus spoken transitions')
